style.css:
/* Midnight Muse - Pinterest */

:root {
  /* swap these colors if you want */
  --my-bg: #121116;
  --my-surface: #1c1a22;
  --my-card: #24212b;
  --my-text: #eeeaf2;
  --my-muted: #a49baa;
  --my-accent: #c6a6d9;
  --my-hover: #342b3b;
}

/* main background and text */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* navigation and header */
header,
[role="banner"] {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  border-color: #302b37 !important;
}

/* general text */
h1, h2, h3, h4, p, span, label {
  color: var(--my-text) !important;
}

/* links and accents */
a {
  color: var(--my-accent) !important;
}

/* buttons */
button {
  border-radius: 12px !important;
}

/* search fields */
input,
[role="searchbox"] {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid #393241 !important;
  border-radius: 16px !important;
}

/* image cards */
img {
  border-radius: 12px !important;
}

/* hover softness */
button:hover,
a:hover {
  background-color: var(--my-hover) !important;
}

/* scrollbars */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: #51445b !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-bg) !important;
}
